@st.cache_data(ttl=86400, show_spinner=False)
def load_colombian_airports():
    """Descarga aeropuertos y pistas de OurAirports; filtra Colombia."""
    base = "https://raw.githubusercontent.com/davidmegginson/ourairports-data/main/"
    airports = pd.read_csv(base + "airports.csv", low_memory=False)
    runways = pd.read_csv(base + "runways.csv", low_memory=False)
    airports = airports[
        (airports["iso_country"] == "CO") &
        (airports["type"].isin(["large_airport", "medium_airport", "small_airport"]))
    ].copy()
    airports["icao"] = airports["gps_code"].fillna("").astype(str).str.strip()
    airports.loc[~airports["icao"].str.fullmatch(r"[A-Z0-9]{4}", na=False), "icao"] = ""
    # Se conservan también aeródromos sin código ICAO: podrán seleccionarse
    # y cargar datos de pista/elevación, aunque el METAR automático no aplique.
    airports = airports.drop_duplicates("ident", keep="first")
    runways = runways[(runways["closed"] == 0) & (runways["length_ft"].fillna(0) > 0)].copy()
    longest = (runways.sort_values("length_ft", ascending=False)
               .drop_duplicates("airport_ident")[[
                   "airport_ident", "length_ft", "le_ident", "le_heading_degT", "surface"
               ]])
    airports = airports.merge(longest, left_on="ident", right_on="airport_ident", how="left")
    airports = airports.drop_duplicates("icao", keep="first")
    airports["elevation_m"] = pd.to_numeric(airports["elevation_ft"], errors="coerce").fillna(0) * 0.3048
    airports["runway_m"] = pd.to_numeric(airports["length_ft"], errors="coerce").fillna(0) * 0.3048
    airports = airports.sort_values(["municipality", "name"], na_position="last")
    return airports.reset_index(drop=True)


@st.cache_data(ttl=300, show_spinner=False)
def fetch_latest_metar(icao):
    """Consulta el METAR más reciente de una estación ICAO."""
    url = "https://aviationweather.gov/api/data/metar"
    response = requests.get(
        url, params={"ids": icao, "format": "json"}, timeout=12,
        headers={"User-Agent": "AeroLab-Educational-Tool/1.0"}
    )
    if response.status_code == 204:
        return ""
    response.raise_for_status()
    payload = response.json()
    if not payload:
        return ""
    item = payload[0] if isinstance(payload, list) else payload
    return item.get("rawOb") or item.get("raw_text") or item.get("raw") or ""



@st.cache_data(ttl=600, show_spinner=False)
def fetch_latest_taf(icao):
    """Consulta el TAF más reciente disponible para una estación ICAO."""
    url = "https://aviationweather.gov/api/data/taf"
    response = requests.get(url, params={"ids": icao, "format": "json"}, timeout=12,
                            headers={"User-Agent": "AeroLab-Educational-Tool/1.0"})
    if response.status_code == 204:
        return ""
    response.raise_for_status()
    payload = response.json()
    if not payload:
        return ""
    item = payload[0] if isinstance(payload, list) else payload
    return item.get("rawTAF") or item.get("raw_text") or item.get("rawOb") or item.get("raw") or ""


def fetch_taf_callback(icao, raw_key, input_key, error_key):
    try:
        raw = fetch_latest_taf(icao)
        if raw:
            st.session_state[raw_key] = raw
            st.session_state[input_key] = raw
            st.session_state[error_key] = ""
        else:
            st.session_state[error_key] = "No hay un TAF disponible para esta estación."
    except Exception as exc:
        st.session_state[error_key] = str(exc)


def reset_all_inputs():
    """Limpia los controles para recuperar los valores iniciales del simulador."""
    for key in list(st.session_state.keys()):
        del st.session_state[key]


def interpret_metar(raw, decoded):
    if not raw:
        return ["No hay METAR cargado; se mantienen los valores ISA/manuales."]
    notes = []
    if decoded.get("wind_kt") is not None:
        d = "variable" if decoded.get("wind_dir") is None else f"desde {decoded['wind_dir']:03d}°"
        notes.append(f"Viento: {d}, {decoded['wind_kt']} kt. La componente de pista depende del rumbo seleccionado.")
    if decoded.get("temperature_c") is not None:
        notes.append(f"Temperatura observada: {decoded['temperature_c']} °C; se usa para estimar la desviación ISA del escenario.")
    if decoded.get("qnh_hpa") is not None:
        notes.append(f"QNH: {decoded['qnh_hpa']:.1f} hPa; se utiliza en la estimación de presión/densidad del modelo.")
    if decoded.get("visibility_m") is not None:
        vis = "10 km o más" if decoded['visibility_m'] >= 10000 else f"{decoded['visibility_m']} m"
        notes.append(f"Visibilidad reportada: {vis}.")
    clouds = re.findall(r"\b(FEW|SCT|BKN|OVC)(\d{3})(CB|TCU)?\b", raw)
    if clouds:
        labels={"FEW":"pocas nubes", "SCT":"nubes dispersas", "BKN":"cielo fragmentado", "OVC":"cubierto"}
        notes.append("Nubosidad: " + "; ".join(f"{labels[k]} a {int(h)*100} ft" + (f" ({kind})" if kind else "") for k,h,kind in clouds) + ".")
    wx = [x for x in re.findall(r"(?<![A-Z])[-+]?\b(?:DZ|RA|SN|SG|IC|PL|GR|GS|UP|BR|FG|FU|VA|DU|SA|HZ|PY|PO|SQ|FC|SS|DS|TS)\b", raw)]
    if wx:
        notes.append("Fenómenos codificados presentes: " + ", ".join(dict.fromkeys(wx)) + ".")
    if not notes:
        notes.append("METAR cargado. Revisa el texto bruto y la hora de observación; la lectura automática es parcial.")
    return notes


def interpret_taf(raw):
    if not raw:
        return ["No hay TAF cargado para interpretar."]
    notes=[]
    if "AMD" in raw: notes.append("TAF enmendado (AMD).")
    if "COR" in raw: notes.append("TAF corregido (COR).")
    validity=re.search(r"\b(\d{4}/\d{4})\b", raw)
    if validity: notes.append(f"Periodo de validez codificado: {validity.group(1)} (días/horas UTC).")
    if re.search(r"\bFM\d{6}\b", raw): notes.append("FM: indica un cambio de condiciones desde la hora UTC indicada.")
    if "BECMG" in raw: notes.append("BECMG: transición gradual hacia las condiciones siguientes.")
    if "TEMPO" in raw: notes.append("TEMPO: variaciones temporales durante el intervalo indicado.")
    if re.search(r"\bPROB(?:30|40)\b", raw): notes.append("PROB30/PROB40: grupo de probabilidad del 30 % o 40 %.")
    winds=re.findall(r"\b(\d{3}|VRB)(\d{2,3})(?:G(\d{2,3}))?KT\b", raw)
    if winds:
        w=winds[0]; direction="variable" if w[0]=="VRB" else f"{w[0]}°"
        notes.append(f"Primer grupo de viento: {direction}, {w[1]} kt" + (f", rachas {w[2]} kt." if w[2] else "."))
    vis=re.findall(r"\b(9999|[0-9]{4})\b", raw)
    if vis:
        notes.append("Visibilidad en el primer grupo: " + ("10 km o más." if vis[0]=="9999" else f"{int(vis[0])} m."))
    clouds=re.findall(r"\b(FEW|SCT|BKN|OVC)(\d{3})(CB|TCU)?\b", raw)
    if clouds:
        notes.append("Grupos de nubes: " + ", ".join(f"{k}{h}"+(kind or "") for k,h,kind in clouds[:5]) + ".")
    notes.append("Interpretación automática orientativa: confirma siempre horarios, grupos y fenómenos en el TAF oficial vigente.")
    return notes


def isa_pressure_at_altitude_ft(alt_ft):
    h=float(alt_ft)*0.3048
    t0=288.15; p0=101325.0; lapse=0.0065
    if h <= 11000.0:
        return p0*(1.0-lapse*h/t0)**(G/(R*lapse))
    p11=p0*(1.0-lapse*11000.0/t0)**(G/(R*lapse))
    return p11*np.exp(-G*(h-11000.0)/(R*216.65))


def cas_from_mach_at_altitude(mach, alt_ft):
    """Convierte Mach a CAS mediante presión de impacto compresible e ISA."""
    p=isa_pressure_at_altitude_ft(alt_ft)
    qc=p*((1.0+0.2*mach**2)**3.5-1.0)
    mach_cas=np.sqrt(max(0.0,5.0*((qc/101325.0+1.0)**(2.0/7.0)-1.0)))
    return mach_cas*661.4788


def a320_operational_speed_envelope():
    """Límite superior VMO/MMO para A320-200, ISA; no es un diagrama V-n."""
    alt=np.linspace(0.0,39100.0,300)
    cas_mmo=np.array([cas_from_mach_at_altitude(0.82,h) for h in alt])
    cas_limit=np.minimum(350.0,cas_mmo)
    cross_idx=int(np.argmin(np.abs(cas_mmo-350.0)))
    return alt, cas_limit, float(alt[cross_idx])

def fetch_metar_callback(icao, raw_key, input_key, error_key):
    """Callback Streamlit: actualiza el METAR antes de reconstruir la interfaz."""
    try:
        raw = fetch_latest_metar(icao)
        if raw:
            st.session_state[raw_key] = raw
            st.session_state[input_key] = raw
            st.session_state[error_key] = ""
        else:
            st.session_state[error_key] = "La estación no tiene un METAR reciente disponible."
    except Exception as exc:
        st.session_state[error_key] = str(exc)


def decode_metar(raw):
    """Extrae variables básicas de un METAR sin sustituir una decodificación oficial."""
    result = {"temperature_c": None, "wind_dir": None, "wind_kt": None,
              "qnh_hpa": None, "visibility_m": None}
    if not raw:
        return result
    m = re.search(r"\b(\d{3}|VRB)(\d{2,3})(?:G(\d{2,3}))?KT\b", raw)
    if m:
        result["wind_dir"] = None if m.group(1) == "VRB" else int(m.group(1))
        result["wind_kt"] = int(m.group(3) or m.group(2))
    m = re.search(r"\b(M?\d{2})/(?:M?\d{2}|//)\b", raw)
    if m:
        t = m.group(1)
        result["temperature_c"] = -int(t[1:]) if t.startswith("M") else int(t)
    m = re.search(r"\bQ(\d{4})\b", raw)
    if m:
        result["qnh_hpa"] = float(m.group(1))
    else:
        m = re.search(r"\bA(\d{4})\b", raw)
        if m:
            result["qnh_hpa"] = round(int(m.group(1)) * 0.01 * 33.8638867, 1)
    m = re.search(r"\b(9999|[0-9]{4})\b", raw)
    if m:
        result["visibility_m"] = 10000 if m.group(1) == "9999" else int(m.group(1))
    return result


