    taf_text = st.text_area("TAF manual o descargado", value=st.session_state.get(taf_key, ""), key=taf_input_key, height=90)
    st.button("Consultar TAF", key=f"fetch_taf_{airport_code}", on_click=fetch_taf_callback,
              args=(airport_code, taf_key, taf_input_key, taf_error_key), disabled=not has_icao_metar, use_container_width=True)
